#include <stdint.h>

uint32_t round_up_pow2_u32(uint32_t x) {
    x = x - 1;
    x |= x >> 1;
    x |= x >> 2;
    x |= x >> 4;
    x |= x >> 8;
    x |= x >> 16;
    return x + 1;
}

#include <stdint.h>

int32_t parity_u32(uint32_t x) {
    x ^= x >> 16;
    x ^= x >> 8;
    x ^= x >> 4;
    x ^= x >> 2;
    x ^= x >> 1;
    return (int32_t)(x & 1);
}

#include <stdint.h>

uint32_t mulhi_u32_portable(uint32_t u, uint32_t v) {
    uint32_t u0 = u & 0xFFFF, u1 = u >> 16;
    uint32_t v0 = v & 0xFFFF, v1 = v >> 16;
    uint32_t w0 = u0 * v0;
    uint32_t t = u1 * v0 + (w0 >> 16);
    uint32_t w1 = (t & 0xFFFF) + u0 * v1;
    return u1 * v1 + (t >> 16) + (w1 >> 16);
}

#include <stdint.h>

static uint32_t pop(uint32_t x) {
    x = x - ((x >> 1) & 0x55555555u);
    x = (x & 0x33333333u) + ((x >> 2) & 0x33333333u);
    x = (x + (x >> 4)) & 0x0F0F0F0Fu;
    return (x * 0x01010101u) >> 24;
}

int32_t clz_smear_u32(uint32_t x) {
    x |= x >> 1;
    x |= x >> 2;
    x |= x >> 4;
    x |= x >> 8;
    x |= x >> 16;
    return (int32_t)pop(~x);
}

#include <stdint.h>

int32_t floor_log2_smear_u32(uint32_t x) {
    x |= x >> 1;
    x |= x >> 2;
    x |= x >> 4;
    x |= x >> 8;
    x |= x >> 16;
    return __builtin_popcount(x) - 1;
}
